import test from 'node:test';
import assert from 'node:assert/strict';
import {safeSnapshot} from '../src/modules/insight/activity.js';
import {insightScenario} from './insight-helpers.js';
test('activity snapshots exclude arbitrary credential payloads and nested secret links',()=>{
  const safe=safeSnapshot({id:'x',name:'Invite',role:'member',token:'secret',passwordHash:'private',payload:{link:'credential'},resetUrl:'danger'});
  assert.deepEqual(safe,{id:'x',name:'Invite',role:'member'});
});
test('activity persists canonical issue before and after with project issue and actor filters',()=>insightScenario(async({api,org,project,issue,user})=>{
  await api('PATCH','/issues/'+issue.id,{title:'Changed title'});
  const result=await api('GET','/activity?orgId='+org.id+'&projectId='+project.id+'&issueId='+issue.id+'&userId='+user.id);
  assert.equal(result.status,200);assert.equal(result.data.items.length,2);
  assert.equal(result.data.items[0].after.title,'Changed title');assert.equal(result.data.items[0].before.title,issue.title);
  assert(result.data.items.every(item=>item.projectId===project.id&&item.entityId===issue.id));
}));
test('activity rejects missing organization invalid date and inaccessible organization',()=>insightScenario(async({api,member,org})=>{
  assert.equal((await api('GET','/activity')).status,422);
  assert.equal((await api('GET','/activity?orgId='+org.id+'&from=bad')).status,422);
  assert.equal((await member('GET','/activity?orgId=foreign')).status,403);
}));
test('activity visibility filters guests before counts cursors and relation target exposure',()=>insightScenario(async({server,api,org,project,issue})=>{
  const other=(await api('POST','/orgs/'+org.id+'/projects',{key:'HID',name:'Secret'})).data.project;
  const hidden=(await api('POST','/projects/'+other.id+'/issues',{title:'Secret plan'})).data.issue;
  await api('POST','/issues/'+issue.id+'/relations',{targetIssueId:hidden.id,kind:'relates'});
  const guest=server.agent(),signup=await guest('POST','/auth/signup',{name:'Guest',email:'insight-guest@example.test',password:'correct-horse-battery'});
  await api('POST','/orgs/'+org.id+'/members',{userId:signup.data.user.id,role:'guest'});
  await api('POST','/projects/'+project.id+'/guests',{userId:signup.data.user.id});
  const feed=(await guest('GET','/activity?orgId='+org.id+'&limit=200')).data;
  assert(feed.items.length>0);assert(feed.items.every(event=>event.projectId===project.id));assert(!JSON.stringify(feed).includes(hidden.id));
  assert.equal((await guest('GET','/activity?orgId='+org.id+'&projectId='+other.id)).status,403);
}));
test('creators assignees and mentions subscribe automatically without notifying the actor',()=>insightScenario(async({api,member,org,project,issue,user,memberUser})=>{
  const ownerSubscriptions=(await api('GET','/subscriptions?orgId='+org.id)).data.items;
  assert(ownerSubscriptions.some(item=>item.targetId===issue.id&&item.reason==='creator'));
  const assigneeSubscriptions=(await member('GET','/subscriptions?orgId='+org.id)).data.items;
  assert(assigneeSubscriptions.some(item=>item.targetId===issue.id&&item.reason==='assignee'));
  await member('POST','/issues/'+issue.id+'/comments',{body:'Please review @[Owner](user:'+user.id+')'});
  const inbox=(await api('GET','/notifications?orgId='+org.id)).data;
  assert.equal(inbox.unread,1);assert.equal(inbox.items[0].reason,'mention');assert.equal(inbox.items[0].activity.after.issueId,issue.id);
  const memberInbox=(await member('GET','/notifications?orgId='+org.id)).data;
  assert.equal(memberInbox.items.length,1);assert.equal(memberInbox.items[0].reason,'assignment');
}));
test('manual project watch and muted issue watch obey exact personal ownership',()=>insightScenario(async({api,member,org,project,issue})=>{
  await api('DELETE','/subscriptions/issue/'+issue.id);
  await member('PATCH','/issues/'+issue.id,{title:'Muted change'});
  assert.equal((await api('GET','/notifications?orgId='+org.id)).data.items.length,0);
  assert.equal((await api('POST','/subscriptions',{targetType:'project',targetId:project.id})).status,201);
  await member('PATCH','/issues/'+issue.id,{title:'Project watched change'});
  assert.equal((await api('GET','/notifications?orgId='+org.id)).data.items.length,1);
  assert.equal((await member('GET','/subscriptions?orgId='+org.id)).data.items.some(item=>item.targetType==='project'),false);
}));
test('inbox supports read unread and atomic bulk marking while hiding other users ids',()=>insightScenario(async({api,member,org,issue})=>{
  await member('PATCH','/issues/'+issue.id,{title:'One'});await member('PATCH','/issues/'+issue.id,{title:'Two'});
  const inbox=(await api('GET','/notifications?orgId='+org.id)).data;
  assert.equal(inbox.unread,2);const id=inbox.items[0].id;
  assert.equal((await member('PATCH','/notifications/'+id,{read:true})).status,404);
  assert.equal((await api('PATCH','/notifications/'+id,{read:true})).data.notification.read,true);
  assert.equal((await api('POST','/notifications/mark',{ids:[id,'foreign'],read:true})).status,422);
  assert.equal((await api('GET','/notifications?orgId='+org.id)).data.unread,1);
  assert.equal((await api('POST','/notifications/mark',{orgId:org.id,all:true,read:true})).data.changed,2);
  assert.equal((await api('GET','/notifications?orgId='+org.id+'&state=unread')).data.items.length,0);
  assert.equal((await api('PATCH','/notifications/'+id,{read:false})).data.notification.readAt,null);
}));
test('digest batches unread notifications once in shared outbox without invite payloads',()=>insightScenario(async({server,api,member,org,issue})=>{
  await member('PATCH','/issues/'+issue.id,{title:'Digest one'});await member('PATCH','/issues/'+issue.id,{title:'Digest two'});
  const result=await api('POST','/digests',{orgId:org.id});assert.equal(result.status,201);assert.equal(result.data.count,2);
  assert.equal(server.ctx.db.prepare("SELECT count(*) n FROM outbox WHERE kind='digest'").get().n,1);
  assert.equal((await api('POST','/digests',{orgId:org.id})).data.count,0);
  const rows=(await api('GET','/digests?orgId='+org.id)).data.items;assert.equal(rows[0].items.length,2);assert(!JSON.stringify(rows).includes('token'));
  assert.equal((await api('GET','/notifications?orgId='+org.id)).data.unread,2);
}));
test('notification preferences filter mention-only and disable email batches',()=>insightScenario(async({api,member,org,issue,user})=>{
  assert.equal((await api('PATCH','/notification-preferences',{orgId:org.id,emailEnabled:'yes'})).status,422);
  await api('PATCH','/notification-preferences',{orgId:org.id,mentionsOnly:true,emailEnabled:false});
  await member('PATCH','/issues/'+issue.id,{title:'Ignored watcher event'});
  assert.equal((await api('GET','/notifications?orgId='+org.id)).data.unread,0);
  await member('POST','/issues/'+issue.id+'/comments',{body:'@[Owner](user:'+user.id+') mention'});
  assert.equal((await api('GET','/notifications?orgId='+org.id)).data.unread,1);
  assert.equal((await api('POST','/digests',{orgId:org.id})).status,409);
}));
test('revoked project access hides existing inbox subscriptions and digests immediately',()=>insightScenario(async({api,member,org,project,issue,memberUser})=>{
  await api('PATCH','/issues/'+issue.id,{title:'Existing assigned notification'});
  await member('POST','/digests',{orgId:org.id});
  await api('PATCH','/orgs/'+org.id+'/members/'+memberUser.id,{role:'guest'});
  assert.deepEqual((await member('GET','/notifications?orgId='+org.id)).data.items,[]);
  assert.deepEqual((await member('GET','/subscriptions?orgId='+org.id)).data.items,[]);
  assert.equal((await member('GET','/digests?orgId='+org.id)).data.items[0].items.length,0);
}));

import {testServer} from './helpers.js';
export async function insightScenario(fn) {
  const server=await testServer();
  try {
    const api=server.agent(),member=server.agent();
    const auth=await api('POST','/auth/signup',{name:'Owner',email:'insight-owner@example.test',password:'correct-horse-battery'});
    const memberAuth=await member('POST','/auth/signup',{name:'Member',email:'insight-member@example.test',password:'correct-horse-battery'});
    const org=(await api('POST','/orgs',{name:'Insight'})).data.organization;
    await api('POST','/orgs/'+org.id+'/members',{userId:memberAuth.data.user.id,role:'member'});
    const project=(await api('POST','/orgs/'+org.id+'/projects',{key:'INS',name:'Insights'})).data.project;
    const issue=(await api('POST','/projects/'+project.id+'/issues',{title:'Insight activity',assigneeId:memberAuth.data.user.id,estimate:3})).data.issue;
    await fn({server,api,member,user:auth.data.user,memberUser:memberAuth.data.user,org,project,issue,cookie:auth.cookie});
  }finally{await server.close();}
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {activityChanges,activityTitle,notificationPath,feedParameters} from '../src/pages/insight/activity-state.js';
import {connectLive,liveUrl} from '../src/live.js';
test('activity titles preserve issue key and safely present plain title text',()=>assert.equal(activityTitle({after:{key:'INS-1',title:'<script>'}}),'INS-1 · <script>'));
test('activity field changes omit identifiers and unchanged fields',()=>assert.deepEqual(activityChanges({before:{id:'a',title:'Old',priority:2},after:{id:'b',title:'New',priority:2}}),[{key:'title',label:'Title',before:'Old',after:'New'}]));
test('notification links resolve comment activity back to the canonical issue',()=>assert.equal(notificationPath({activity:{entityType:'comment',after:{issueId:'x y'}},projectId:'p'}),'/issues/x%20y'));
test('feed parameters retain valid false zero and filter empty values',()=>assert.deepEqual(feedParameters({orgId:'o',cursor:'',zero:0,flag:false,absent:null}),{orgId:'o',zero:0,flag:false}));
test('live client publishes activity and connection state and releases exactly once',()=>{
  let source;class FakeSource{constructor(url){this.url=url;this.listeners={};source=this;}addEventListener(name,fn){this.listeners[name]=fn;}close(){this.closed=(this.closed??0)+1;}}
  const statuses=[],events=[];const stop=connectLive({orgId:'org a',onStatus:value=>statuses.push(value),onActivity:value=>events.push(value),EventSourceClass:FakeSource});
  assert.equal(source.url,liveUrl({orgId:'org a'}));source.listeners.ready({});source.listeners.activity({data:'{"id":"a"}'});assert.deepEqual(events,[{id:'a'}]);
  stop();stop();assert.equal(source.closed,1);assert.deepEqual(statuses,['connecting','live','paused']);source.listeners.activity({data:'{"id":"b"}'});assert.equal(events.length,1);
});
test('live client reports malformed frames and reconnect state without throwing',()=>{
  let source;class FakeSource{constructor(){source=this;this.listeners={};this.readyState=0;}addEventListener(name,fn){this.listeners[name]=fn;}close(){}}
  const states=[];const stop=connectLive({onStatus:value=>states.push(value),EventSourceClass:FakeSource});source.listeners.activity({data:'bad'});source.listeners.error();assert.deepEqual(states,['connecting','invalid update','reconnecting']);stop();
});
